import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))

        if n == 2:
            x, y = a[0], a[1]
            diff = abs(x - y)
            results.append(str(diff * 2))
        else:
            max_val = max(a)
            results.append(str(max_val * n))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
